var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
System.Action<bool,string> check=(ok,message)=>{if(!ok)throw new System.Exception(message);};
var report=new System.Collections.Generic.List<string>();
var sword=ScriptableObject.CreateInstance<ItemData>();sword.Name="Test Kılıç";sword.itemShape=new System.Collections.Generic.List<Vector2Int>{Vector2Int.zero,new Vector2Int(0,1)};sword.itemOwners=new[]{TowerType.ArrowTower};sword.cost=100;
var crown=ScriptableObject.CreateInstance<ItemData>();crown.Name="Test Taç";crown.itemShape=new System.Collections.Generic.List<Vector2Int>{Vector2Int.zero};crown.itemOwners=new[]{TowerType.ArrowTower};crown.cost=50;
sword.itemIcon=Resources.Load<ItemData>("Data/Items/Shop/Normal/v1_legion_sword").itemIcon;crown.itemIcon=Resources.Load<ItemData>("Data/Items/Shop/Normal/v1_legion_crown").itemIcon;
var recipe=ScriptableObject.CreateInstance<ItemSynergyRecipe>();recipe.targetItem=sword;recipe.supportItem=crown;recipe.cells.Add(new Vector2Int(1,0));recipe.placement=ItemSynergyRecipe.Placement.CellsOrAttached;recipe.bonus=new ItemBonus{flatDamage=5};sword.synergyRecipes.Add(recipe);sword.synergyRecipes.Add(recipe);
var bag=new Backpack(8,8);var host=bag.Place(sword,new Vector2Int(2,2));var piece=bag.Place(crown,new Vector2Int(3,2));check(ItemSynergyCalculator.Additional(bag,host).flatDamage==5,"Position bonus or duplicate recipe");bag.Remove(piece);check(ItemSynergyCalculator.Additional(bag,host).flatDamage==0,"Position bonus removal");
for(int r=0;r<4;r++){bag.Remove(host);check(bag.PlaceExisting(host,new Vector2Int(2,2),r),"Rotation place");var cell=ItemSynergyCalculator.Cells(sword,recipe,host.Origin,r).First();check(bag.PlaceExisting(piece,cell),"Rotated support");check(ItemSynergyCalculator.Additional(bag,host).flatDamage==5,"Rotated bonus");bag.Remove(piece);}
check(bag.TryAttach(host,piece),"Attach");check(!bag.TryAttach(host,new PlacedItem(crown,Vector2Int.zero)),"Attachment cap");check(ItemSynergyCalculator.Additional(bag,host).flatDamage==5,"Attached bonus");bag.Remove(host);var storage=new Backpack(8,8);check(storage.PlaceExisting(host,Vector2Int.zero),"Move host identity");check(piece.Parent==host&&piece.Bag==storage&&host.Attachments.Count==1,"Attachment follows host");check(ItemSynergyCalculator.Additional(bag,host).flatDamage==0,"Foreign bag ignored");storage.Remove(piece);check(piece.Parent==null&&piece.Bag==null,"Detach");check(storage.PlaceExisting(piece,new Vector2Int(5,5)),"Detached placement");report.Add("Position, four rotations, removal, one-time recipe, cap, identity, detach and ownership passed");
var go=UnityEngine.Object.Instantiate(UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/ArcherTower1.prefab"));go.name="SynergyValidationTower";var tower=go.GetComponent<ArcherTower>();typeof(Tower).GetMethod("InitializeTower",flags).Invoke(tower,null);
foreach(var item in tower.Backpack.Items.ToArray())tower.Backpack.Remove(item);
var h=tower.Backpack.Place(sword,Vector2Int.zero);var part=tower.Backpack.Place(crown,new Vector2Int(3,0));tower.CalculateStats();float baseDamage=(float)typeof(Tower).GetField("currentDamage",flags).GetValue(tower);
var ui=BackpackUIManager.Instance;ui.OpenBackpack(tower);Canvas.ForceUpdateCanvases();
System.Func<PlacedItem,BackpackDraggable> visual=item=>((System.Collections.Generic.Dictionary<PlacedItem,GameObject>)typeof(BackpackUIManager).GetField("itemVisuals",flags).GetValue(ui))[item].GetComponent<BackpackDraggable>();
System.Func<RectTransform,int,int,Vector2> point=(rect,x,y)=>RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(new Vector3((x+.5f)*ui.cellSize,-(y+.5f)*ui.cellSize,0)));
System.Func<Vector2,UnityEngine.EventSystems.PointerEventData> ev=pos=>new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=pos};
var drag=visual(part);drag.BeginDrag();check(drag.FinishDrag(ev(point(ui.gridContainer,0,0))),"UI attachment drop");check(h.Attachments.Count==1&&part.Parent==h,"UI attaches existing piece");check(Mathf.Abs((float)typeof(Tower).GetField("currentDamage",flags).GetValue(tower)-baseDamage-5)<.001f,"Flat five damage");
var info=UnityEngine.Object.FindObjectOfType<HoverInfoController>().infoPanel;info.Show(visual(h),new Vector2(600,400));check(info.bodyText.text.Contains("+5 sabit hasar"),"Instance tooltip");
drag=visual(h);drag.BeginDrag();drag.Rotate(1);BackpackDraggable.CancelActiveDrag();check(h.Bag==tower.Backpack&&h.Rotation==0&&part.Parent==h&&part.Bag==tower.Backpack,"Cancel host rotation preserves part");
drag=visual(part);drag.BeginDrag();check(drag.FinishDrag(ev(point(ui.gridContainer,3,0))),"Detach by dragging badge");check(part.Parent==null&&h.Attachments.Count==0,"Badge detached");
drag=visual(part);drag.BeginDrag();check(drag.FinishDrag(ev(point(ui.gridContainer,0,0))),"Reattach");
drag=visual(h);drag.BeginDrag();check(drag.FinishDrag(ev(point(ui.storageGridContainer,0,0))),"Move host into storage");check(part.Bag==tower.Storage&&part.Parent==h,"Storage child ownership");check(Mathf.Abs((float)typeof(Tower).GetField("currentDamage",flags).GetValue(tower)-baseDamage)<.001f,"Storage no buff");
drag=visual(h);drag.BeginDrag();check(!drag.FinishDrag(ev(new Vector2(-100,-100))),"Invalid drop must fail");check(h.Bag==tower.Storage&&part.Parent==h,"Failed drop restores group");
drag=visual(h);drag.BeginDrag();check(drag.FinishDrag(ev(point(ui.gridContainer,0,0))),"Return to backpack");
// Sell host only: attached part is retained, and not paid out as a sale.
int gold=EconomyManager.Gold;drag=visual(h);drag.BeginDrag();check(drag.FinishDrag(ev(RectTransformUtility.WorldToScreenPoint(null,ui.sellArea.TransformPoint(ui.sellArea.rect.center)))),"Host sale");check(EconomyManager.Gold==gold+EconomyManager.GetSellValue(sword)&&part.Bag==tower.Storage&&part.Parent==null,"Sale salvage and payout");report.Add("UI attach, detach, cancel/failed drop, host storage, zero storage buffs, instance tooltip and sale salvage passed");
// Shop item can attach directly, charging once; full attachment slot rejects another purchase.
h=tower.Backpack.Place(sword,Vector2Int.zero);ui.RefreshItemVisuals();EconomyManager.Gold=200;
var ghost=UnityEngine.Object.Instantiate(ui.itemVisualPrefab,ui.combinedPanel.transform);drag=ghost.GetComponent<BackpackDraggable>();drag.InitializeFromShop(crown);drag.BeginDrag();check(drag.FinishDrag(ev(point(ui.gridContainer,0,0))),"Shop attach");check(EconomyManager.Gold==150&&h.Attachments.Count==1,"Single purchase charge");
ghost=UnityEngine.Object.Instantiate(ui.itemVisualPrefab,ui.combinedPanel.transform);drag=ghost.GetComponent<BackpackDraggable>();drag.InitializeFromShop(crown);drag.BeginDrag();check(!drag.FinishDrag(ev(point(ui.gridContainer,0,0)))&&EconomyManager.Gold==150,"Reject full attachment without charge");report.Add("Shop attachment purchases charged once; rejected purchase charged zero");
// A successful wave evolves only grid participants; attached pieces survive even with a full storage.
foreach(var item in tower.Storage.Items.ToArray())tower.Storage.Remove(item);
for(int y=0;y<tower.Storage.Height;y++)for(int x=0;x<tower.Storage.Width;x++)tower.Storage.Place(crown,new Vector2Int(x,y));
var neighbor=tower.Backpack.Place(crown,new Vector2Int(1,0));tower.Backpack.Place(crown,new Vector2Int(4,4));var attached=h.Attachments[0];
var result=ScriptableObject.CreateInstance<ItemData>();result.Name="Test Evrim";result.itemOwners=new[]{TowerType.ArrowTower};result.itemShape=new System.Collections.Generic.List<Vector2Int>();for(int y=0;y<5;y++)for(int x=0;x<5;x++)result.itemShape.Add(new Vector2Int(x,y));
var evolution=ScriptableObject.CreateInstance<ItemEvolutionRecipe>();evolution.first=sword;evolution.second=crown;evolution.result=result;tower.evolutionRecipes=new System.Collections.Generic.List<ItemEvolutionRecipe>{evolution};
tower.Evolution.BeginWave(42);check(tower.Evolution.Pending.Count==1&&tower.Backpack.Contains(h),"No early evolution");tower.Evolution.CompleteWave(42);check(!tower.Backpack.Contains(h)&&!tower.Backpack.Contains(neighbor),"Consume only pair");check(tower.Evolution.Deliveries.Count==2&&tower.Evolution.Deliveries.Any(d=>d.Content==attached)&&tower.Evolution.Deliveries.Any(d=>d.Item==result),"Full storage preserves attachment and evolved result");tower.Evolution.CompleteWave(42);check(tower.Evolution.Deliveries.Count==2,"No double evolution");
var delivery=tower.Evolution.Deliveries.Single(d=>d.Content==attached);tower.Storage.Remove(tower.Storage.GetItemAt(Vector2Int.zero));ui.RefreshItemVisuals();ghost=UnityEngine.Object.Instantiate(ui.itemVisualPrefab,ui.combinedPanel.transform);drag=ghost.GetComponent<BackpackDraggable>();drag.InitializeDelivery(tower,delivery);drag.BeginDrag();check(drag.FinishDrag(ev(point(ui.storageGridContainer,0,0))),"Claim attachment delivery");check(attached.Bag==tower.Storage&&!tower.Evolution.Contains(delivery),"Delivery identity preserved");report.Add("One-wave evolution preserved; full storage queues part and result; repeat completion and delivery claim passed");
info.Hide();ui.CloseBackpack();return report;
